namespace BeamScheduleFormatter {
sealed partial class CalculationDocument:IDisposable {
 internal readonly List<Action<Graphics>> Sheets=new List<Action<Graphics>>();readonly List<IDisposable> owned=new List<IDisposable>();
 internal bool FullPage;internal EngineeringReport ReportFile;internal string Title;internal readonly ProjectInformation Project;
 readonly int projectCoverCount;
 /* page size in points: A4 portrait by default; A3 landscape for drawings (owner, 19 November 2026: "Gamit ng A3 para ok") */
 internal float PageWidth=595.28f,PageHeight=841.89f;internal bool A3{get{return PageWidth>1000||PageHeight>1000;}}
 internal void UseA3Landscape(){PageWidth=1190.55f;PageHeight=841.89f;}
 internal CalculationDocument(string title,bool fullPage=false){Title=title;Project=ProjectInfoStore.Read();FullPage=fullPage;if(!fullPage&&ProjectReportHeader.Lines(Project,515).Count>4){var metadata=new EngineeringReport{Title="Project information",Project=Project.Name,Location=Project.Location,Office=Project.Office};using(var cover=FromEngineering(metadata)){Sheets.AddRange(cover.Sheets);}projectCoverCount=Sheets.Count;}}
 internal T Own<T>(T item) where T:IDisposable{owned.Add(item);return item;}
 internal static void Text(Graphics g,string text,float x,float y,float width,float height,float size=7,bool bold=false,Color? color=null){using(var font=new Font("Segoe UI",Math.Max(7,size),bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Point))using(var brush=new SolidBrush(color??PowTheme.Ink))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisWord})g.DrawString(text,font,brush,new RectangleF(x,y,width,height),format);}
 internal static void Section(Graphics g,string title,float y,float width){using(var brush=new SolidBrush(ModernUi.Soft))g.FillRectangle(brush,36,y,width,26);using(var brush=new SolidBrush(PowTheme.Teal))g.FillRectangle(brush,36,y,3,26);Text(g,title,46,y+5,width-23,20,10,true);}
 internal static void Section(Graphics g,string title,float y){using(var brush=new SolidBrush(ModernUi.Soft))g.FillRectangle(brush,36,y,523,26);using(var brush=new SolidBrush(PowTheme.Teal))g.FillRectangle(brush,36,y,3,26);Text(g,title,46,y+5,500,20,10,true);}
 internal static void Table(Graphics g,string[] headers,IList<string[]> rows,float y,float[] widths,float rowHeight=30){float x=36;for(int c=0;c<headers.Length;c++){using(var brush=new SolidBrush(PowTheme.Ink))g.FillRectangle(brush,x,y,widths[c],34);Text(g,headers[c],x+5,y+4,widths[c]-8,29,7,true,Color.White);x+=widths[c];}y+=34;for(int r=0;r<rows.Count;r++){x=36;for(int c=0;c<headers.Length;c++){using(var brush=new SolidBrush(r%2==0?Color.White:ModernUi.Soft))g.FillRectangle(brush,x,y,widths[c],rowHeight);Text(g,c<rows[r].Length?rows[r][c]:"",x+5,y+4,widths[c]-8,rowHeight-5,7);x+=widths[c];}using(var pen=new Pen(PowTheme.Line,.5f))g.DrawLine(pen,36,y+rowHeight,559,y+rowHeight);y+=rowHeight;}}
 internal void Draw(Graphics g,int page){using(var paper=new ReportPaperScope()){var saved=g.Save();try{g.PageUnit=GraphicsUnit.Point;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;g.Clear(Color.White);if(FullPage||page<projectCoverCount){Sheets[page](g);return;}PdfBrand.Draw(g,PageWidth,PageHeight);float W=PageWidth,H=PageHeight;
  using(var brush=new SolidBrush(PowTheme.Teal))g.FillRectangle(brush,36,28,30,3);Text(g,"DTCE / CALCULATION REPORT",76,23,470,18,8,true,PowTheme.Muted);Text(g,Title,36,47,W-72,28,16,true);
  float projectY=80;if(projectCoverCount>0)Text(g,"Project information: see opening project information pages.",36,projectY,523,16,8);else foreach(string line in ProjectReportHeader.Lines(Project,515)){Text(g,line,36,projectY,523,12,8);projectY+=10;}
  Sheets[page](g);using(var pen=new Pen(PowTheme.Line))g.DrawLine(pen,36,H-39,W-36,H-39);Text(g,"DTCE Tool Kit v"+Engine.Version+" · "+DateTime.Now.ToString("yyyy-MM-dd")+(A3?" · A3":""),36,H-30,400,16,7,false,PowTheme.Muted);Text(g,(page+1)+" / "+Sheets.Count,W-85,H-30,49,16,8,true);
 }finally{g.Restore(saved);}}}
 internal static CalculationDocument FromText(string report){return FromEngineering(ProfessionalReportExport.FromText(report));}
 internal PrintDocument Printer(){int page=0;var print=new PrintDocument{DocumentName=Title,OriginAtMargins=false};if(A3){print.DefaultPageSettings.PaperSize=new PaperSize("A3",1169,1654);print.DefaultPageSettings.Landscape=PageWidth>PageHeight;}else print.DefaultPageSettings.PaperSize=new PaperSize("A4",827,1169);print.BeginPrint+=(s,e)=>page=0;print.PrintPage+=(s,e)=>{var state=e.Graphics.Save();try{e.Graphics.PageUnit=GraphicsUnit.Point;e.Graphics.TranslateTransform(-e.PageSettings.HardMarginX*.72f,-e.PageSettings.HardMarginY*.72f);Draw(e.Graphics,page++);}finally{e.Graphics.Restore(state);}e.HasMorePages=page<Sheets.Count;};return print;}
 internal void WritePdf(string path){var security=new PdfSecurity();var objects=new List<byte[]>();Action<string> add=s=>objects.Add(Encoding.ASCII.GetBytes(s));int count=Sheets.Count;
  add("<< /Type /Catalog /Pages 2 0 R >>");add("<< /Type /Pages /Count "+count+" /Kids ["+string.Join(" ",Enumerable.Range(0,count).Select(i=>(3+i*3)+" 0 R"))+"] >>");
  for(int i=0;i<count;i++){int page=3+i*3,image=page+1,content=page+2;string box=PageWidth.ToString("0.##",CultureInfo.InvariantCulture)+" "+PageHeight.ToString("0.##",CultureInfo.InvariantCulture);int bw=(int)Math.Round(PageWidth/72*300),bh=(int)Math.Round(PageHeight/72*300);add("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 "+box+"] /Resources << /XObject << /PageImage "+image+" 0 R >> >> /Contents "+content+" 0 R >>");
   using(var bitmap=new Bitmap(bw,bh)){bitmap.SetResolution(300,300);using(var g=Graphics.FromImage(bitmap))Draw(g,i);using(var stream=new MemoryStream()){using(var quality=new EncoderParameters(1)){quality.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,95L);bitmap.Save(stream,ImageCodecInfo.GetImageEncoders().First(codec=>codec.FormatID==ImageFormat.Jpeg.Guid),quality);}objects.Add(Stream("/Type /XObject /Subtype /Image /Width "+bw+" /Height "+bh+" /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode",security.Encrypt(stream.ToArray(),image)));}}
   objects.Add(Stream("",security.Encrypt(Encoding.ASCII.GetBytes("q "+PageWidth.ToString("0.##",CultureInfo.InvariantCulture)+" 0 0 "+PageHeight.ToString("0.##",CultureInfo.InvariantCulture)+" 0 0 cm /PageImage Do Q"),content)));
  }
  int encrypt=objects.Count+1;add(security.Dictionary());string full=Path.GetFullPath(path),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var file=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){Action<string> put=s=>{var bytes=Encoding.ASCII.GetBytes(s);file.Write(bytes,0,bytes.Length);};put("%PDF-1.6\n");var offsets=new List<long>{0};for(int i=0;i<objects.Count;i++){offsets.Add(file.Position);put((i+1)+" 0 obj\n");file.Write(objects[i],0,objects[i].Length);put("\nendobj\n");}long xref=file.Position;put("xref\n0 "+offsets.Count+"\n0000000000 65535 f \n");foreach(long offset in offsets.Skip(1))put(offset.ToString("D10",CultureInfo.InvariantCulture)+" 00000 n \n");put("trailer\n<< /Size "+offsets.Count+" /Root 1 0 R /Encrypt "+encrypt+" 0 R /ID [<"+PdfSecurity.Hex(security.Id)+"><"+PdfSecurity.Hex(security.Id)+">] >>\nstartxref\n"+xref+"\n%%EOF\n");}PdfProtection.WriteFinal(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}
 }
 static byte[] Stream(string dictionary,byte[] data){return Encoding.ASCII.GetBytes("<< "+dictionary+" /Length "+data.Length+" >>\nstream\n").Concat(data).Concat(Encoding.ASCII.GetBytes("\nendstream")).ToArray();}
 public void Dispose(){foreach(var item in owned)item.Dispose();owned.Clear();}
}
class CalculationReportView:ScrollableControl {
 CalculationDocument document;bool owns;float scale;int pw,ph;internal int PageCount{get{return document==null?0:document.Sheets.Count;}}
 internal CalculationReportView(){DoubleBuffered=true;ResizeRedraw=true;AutoScroll=true;BackColor=Color.FromArgb(224,230,236);}
 internal void SetDocument(CalculationDocument value,bool own=true){if(owns&&document!=null)document.Dispose();document=value;owns=own;AutoScrollPosition=Point.Empty;LayoutPages();}
 void LayoutPages(){float W=document==null?595.28f:document.PageWidth,H=document==null?841.89f:document.PageHeight;scale=Math.Max(.3f,Math.Min(1.8f,(ClientSize.Width-44)/W));pw=(int)(W*scale);ph=(int)(H*scale);AutoScrollMinSize=new Size(pw+40,PageCount*(ph+24)+24);Invalidate();}
 protected override void OnResize(EventArgs e){base.OnResize(e);LayoutPages();}
 protected override void OnScroll(ScrollEventArgs e){base.OnScroll(e);Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(document==null||ph<=0){TextRenderer.DrawText(e.Graphics,"Calculate to generate the report.",ModernUi.Body,new Point(24,24),PowTheme.Muted);return;}for(int i=Math.Max(0,-AutoScrollPosition.Y/(ph+24));i<PageCount;i++){int y=16+i*(ph+24)+AutoScrollPosition.Y;if(y>Height)break;int x=Math.Max(16,(ClientSize.Width-pw)/2)+AutoScrollPosition.X;var saved=e.Graphics.Save();try{e.Graphics.SetClip(new Rectangle(x,y,pw,ph));e.Graphics.PageUnit=GraphicsUnit.Point;e.Graphics.TranslateTransform(x*72/e.Graphics.DpiX,y*72/e.Graphics.DpiY);e.Graphics.ScaleTransform(scale*72/e.Graphics.DpiX,scale*72/e.Graphics.DpiY);document.Draw(e.Graphics,i);}finally{e.Graphics.Restore(saved);}}}
 internal static void ShowReport(IWin32Window owner,CalculationDocument doc){using(var form=new Form{Text="Calculation report / Print preview",Width=1150,Height=850,MinimumSize=new Size(760,600),StartPosition=FormStartPosition.CenterParent})using(var printer=doc.Printer()){
  var view=new CalculationReportView{Dock=DockStyle.Fill};view.SetDocument(doc,false);var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=46,Padding=new Padding(7)};var print=new Button{Text="Print report…",AutoSize=true};print.Click+=(s,e)=>{using(var dialog=new PrintDialog{Document=printer,UseEXDialog=true})if(dialog.ShowDialog(form)==DialogResult.OK)printer.Print();};var save=new Button{Text="Save PDF",AutoSize=true};save.Click+=(s,e)=>{using(var dialog=new SaveFileDialog{Filter="PDF|*.pdf",FileName="DTCE-Calculation-Report.pdf"})if(dialog.ShowDialog(form)==DialogResult.OK)doc.WritePdf(dialog.FileName);};tools.Controls.Add(print);tools.Controls.Add(save);if(doc.ReportFile!=null){var file=new Button{Text="Export report file",AutoSize=true};file.Click+=(sender,args)=>ProfessionalReportExport.Show(form,doc.ReportFile);tools.Controls.Add(file);}tools.Controls.Add(new Label{Text=doc.Sheets.Count+" pages · scroll to review",AutoSize=true,Padding=new Padding(10,7,0,0)});form.Controls.Add(view);form.Controls.Add(tools);PowTheme.Apply(form);form.ShowDialog(owner);
 }}
 protected override void Dispose(bool disposing){if(disposing&&owns&&document!=null)document.Dispose();base.Dispose(disposing);}
}
